	stdout, stderr, code := runServedCLICommand(t, rt.Endpoint, []string{"run", "fork", started.RunID, "--at-event", published.EventID, "--allow-source-freeze", "--idempotency-key", forkParams["idempotency_key"].(string), "--json"})
	if code != 0 || strings.TrimSpace(stderr) != "" {
		t.Fatalf("swarm run fork code=%d stderr=%q stdout=%s\nsource debug:\n%s", code, stderr, stdout, servedInspectionRunDebugSummary(rt.ReceiverStateReader, started.RunID))
	}
	var fork apiv1.RunForkExecutionResult
	if err := json.Unmarshal([]byte(stdout), &fork); err != nil {
		t.Fatalf("decode swarm run fork result: %v\n%s", err, stdout)
	}
	if fork.SourceRunID != started.RunID || fork.ForkEventID != published.EventID || fork.ForkRunID == "" || fork.SourceFrozen || fork.SourceRunStatus != "running" || fork.ExecutedEventCount != 1 {
		t.Fatalf("run.fork result = %#v", fork)
	}
	var replay apiv1.RunForkExecutionResult
	requireServedJSONRPCResult(t, rt.Endpoint, "run.fork", forkParams, &replay)
	if !reflect.DeepEqual(replay, fork) {
		t.Fatalf("run.fork idempotent replay = %#v, want exact %#v", replay, fork)
	}
	forkCountQuery := `SELECT COUNT(*) FROM runs WHERE forked_from_run_id = ? AND forked_from_event_id = ?`
	if rt.Backend == "postgres" {
		forkCountQuery = `SELECT COUNT(*) FROM runs WHERE forked_from_run_id = $1::uuid AND forked_from_event_id = $2::uuid`
	}
	var forkRows int
	if err := rt.DB.QueryRowContext(context.Background(), forkCountQuery, started.RunID, published.EventID).Scan(&forkRows); err != nil || forkRows != 1 {
		t.Fatalf("%s durable fork rows = %d, err=%v, want 1", rt.Backend, forkRows, err)
	}
	waitServedRunDeliveryQuiescence(t, rt.ReadRunDeliveries, fork.ForkRunID)
	deadline := time.Now().Add(servedProofPollDeadline)
	for {
		var candidateSettled bool
		if err := rt.DB.QueryRow(`SELECT completion_due_at IS NULL FROM runs WHERE run_id=$1`, fork.ForkRunID).Scan(&candidateSettled); err != nil {
			t.Fatal(err)
		}
		if candidateSettled {
			break
		}
		if time.Now().After(deadline) {
			t.Fatalf("fork completion candidate did not settle before refusal baseline: %s", servedInspectionRunDebugSummary(rt.ReceiverStateReader, fork.ForkRunID))
		}
		time.Sleep(10 * time.Millisecond)
	}
	beforeRefusal := snapshotForkReceiverApplication(t, rt.ReadApplicationSnapshot)
	refused := requireServedJSONRPCError(t, rt.Endpoint, "event.publish", map[string]any{"bundle_hash": rt.BundleHash, "run_id": fork.ForkRunID, "event_name": "item.processed", "payload": map[string]any{"item_id": "review"}, "idempotency_key": "issue-2361-" + rt.Backend + "-fork-completion"})
	if refused.Data["code"] != "SELECTED_FORK_CONTROL_UNSUPPORTED" {
		t.Fatalf("selected ingress refusal = %+v", refused)
	}
	var bindingID string
	if err := rt.DB.QueryRow(`SELECT binding_id FROM run_fork_selected_contract_bindings WHERE fork_run_id=$1`, fork.ForkRunID).Scan(&bindingID); err != nil {
		t.Fatal(err)
	}
	details, ok := refused.Data["details"].(map[string]any)
	if !ok || details["run_id"] != fork.ForkRunID || details["binding_id"] != bindingID || details["operation"] != "event.publish" {
		t.Fatalf("selected ingress refusal lost exact binding: %+v", refused)
	}
	if afterRefusal := snapshotForkReceiverApplication(t, rt.ReadApplicationSnapshot); !reflect.DeepEqual(beforeRefusal, afterRefusal) {
		t.Fatalf("refused selected ingress changed persisted state: tables=%v", forkReceiverChangedTables(beforeRefusal, afterRefusal))
	}
	var stopped struct {
		OK bool `json:"ok"`
	}
	requireServedJSONRPCResult(t, rt.Endpoint, "run.stop", map[string]any{"run_id": fork.ForkRunID}, &stopped)
	if !stopped.OK {
		t.Fatal("selected stop lost terminal acknowledgment")
	}
	requireServedRunStatusWithDebug(t, rt.Endpoint, rt.ReceiverStateReader, rt.Backend, fork.ForkRunID, "cancelled")
	requireServedRunForkStoppedReplay(t, rt.DB, fork.ForkRunID)
	for method, params := range map[string]map[string]any{"run.get": {"run_id": fork.ForkRunID}, "entity.list": {"run_id": fork.ForkRunID, "limit": 500}, "event.list": {"filter": map[string]any{"run_id": fork.ForkRunID}, "limit": 500}, "conversation.list": {"run_id": fork.ForkRunID, "limit": 500}} {
		var readback map[string]any
		requireServedJSONRPCResult(t, rt.Endpoint, method, params, &readback)
		if len(readback) == 0 {
			t.Fatalf("%s returned empty result envelope", method)
		}
	}
	requireServedStatusCLIReadback(t, rt.Endpoint, fork.ForkRunID, "  cancelled")
	requireServedParitySettlementPostconditions(t, rt.Endpoint, rt.ReceiverStateReader, rt.Backend, fork.ForkRunID, servedparity.MustScenario(servedparity.ScenarioRunForkLifecycle))
}

