				}
				if failSecond {
					if prepared.err == nil {
						t.Fatal("canceled second candidate succeeded")
					}
					return
				}
				if prepared.err != nil {
					t.Fatal(prepared.err)
				}
				if failure == "registered_release" {
					assertRegisteredStartupAbort(t, cancel, prepared.release, candidates, manager, false)
					return
				}
				if err := manager.ReleaseResetExecution(definitions...); err != nil {
					t.Fatal(err)
				}
				if failure == "reset_active_release" {
					assertRegisteredStartupAbort(t, cancel, prepared.release, candidates, manager, true)
					return
				}
				if err := prepared.release(); err != nil {
					t.Fatal(err)
				}
				supervisor.mu.Lock()
				supervisor.resetting = false
				supervisor.mu.Unlock()
				published := requireServedEventPublishRPCResult(t, server.URL+"/v1/rpc", map[string]any{"event_name": "item.received", "bundle_hash": candidates[1].sourceArtifactFact.BundleHash(), "payload": map[string]any{"item_id": "after-convergence"}, "idempotency_key": uuid.NewString()})
				waitForServedEventPublishNodeDeliveryLifecycle(t, selectedStoreDatabaseForTest(t, stores), requireReceiverProofStateReader(t, candidates[1].runtime.Bus.Store()), backend, published.RunID, published.EventID, probe)
				for _, candidate := range candidates {
					grant, err := candidate.runtime.CurrentStartupGrantEvidence()
					if err != nil || grant.State != startupownership.GrantAdmitted {
						t.Fatalf("converged candidate failed to execute: %+v, %v", grant, err)
					}
				}
			})
		}
	}
