					if response.Error == nil || response.Error.Data["code"] != apiv1.BundleUnavailableCode {
						t.Fatalf("cleared source execution error = %+v, want %s", response.Error, apiv1.BundleUnavailableCode)
					}
				} else {
					var retainedSource []byte
					if err := func() error {
